def parse_csv_line(line):
    """
    Parse a single CSV line into a list of fields.
    Handles quoted fields, commas inside quotes, and doubled quotes.
    """
    fields = []
    field = ''
    in_quotes = False
    i = 0
    while i < len(line):
        c = line[i]
        if in_quotes:
            if c == '"':
                # If the next character is also a quote, it's an escaped quote
                if i + 1 < len(line) and line[i + 1] == '"':
                    field += '"'
                    i += 1  # Skip the escaped quote
                else:
                    in_quotes = False
            else:
                field += c
        else:
            if c == ',':
                fields.append(field)
                field = ''
            elif c == '"':
                in_quotes = True
            else:
                field += c
        i += 1
    # Append the last field
    fields.append(field)
    return fields
