    in_quotes = False
    i = 0
    while i < len(line):
        c = line[i]
        if in_quotes:
            if c == '"':
                # Check for escaped quote
                if i + 1 < len(line) and line[i + 1] == '"':
                    field.append('"')
                    i += 1
                else:
                    in_quotes = False
            else:
                field.append(c)
        else:
            if c == ',':
                fields.append(''.join(field))
                field = []
            elif c == '"':
                in_quotes = True
            else:
                field.append(c)
        i += 1
    # Append the last field
    fields.append(''.join(field))
    return fields
