def is_balanced(s):
    """
    Return True if the string s contains only correctly nested and matched
    parentheses (), brackets [], and braces {}. Other characters are ignored.
    """
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    opening = set(pairs.values())

    for c in s:
        if c in opening:
            stack.append(c)
        elif c in pairs:
            if not stack or stack[-1] != pairs[c]:
                return False
            stack.pop()

    return not stack
```

