import subprocess

def capture_stdout(argv):
    completed = subprocess.run(
        argv,
        capture_output=True,
        text=True,
        shell=False,
    )
    if completed.returncode != 0:
        raise RuntimeError(f"Command {' '.join(argv)} failed with exit code {completed.returncode}")
    return completed.stdout.rstrip()

